use std::sync::{Arc, Mutex};
use std::thread;

fn t1(a: Arc<Mutex<()>>, b: Arc<Mutex<()>>) -> usize {
    let guard_a = a.lock().unwrap();
    let guard_b = b.lock().unwrap();

    let result = 1;

    drop(guard_b);
    drop(guard_a);
    result
}

fn t2(a: Arc<Mutex<()>>, b: Arc<Mutex<()>>) -> usize {
    let guard_a = a.lock().unwrap();
    let guard_b = b.lock().unwrap();

    let result = 1;

    drop(guard_b);
    drop(guard_a);
    result
}

fn main() {
    let a = Arc::new(Mutex::new(()));
    let b = Arc::new(Mutex::new(()));

    let worker_t1 = {
        let a = Arc::clone(&a);
        let b = Arc::clone(&b);
        thread::spawn(move || t1(a, b))
    };

    let worker_t2 = {
        let a = Arc::clone(&a);
        let b = Arc::clone(&b);
        thread::spawn(move || t2(a, b))
    };

    let result_t1 = worker_t1.join().unwrap();
    let result_t2 = worker_t2.join().unwrap();

    println!("DONE t1={result_t1} t2={result_t2}");
}
